class RecordingLedger extends Ledger {
  private val balances = mutable.Map.empty[String, Long].withDefaultValue(0L)
  private val journal = mutable.ArrayBuffer.empty[Operation]

  override def deposit(id: String, amount: Long): Unit = {
    balances.update(id, balances(id) + amount)          // working behaviour
    journal += Operation("deposit", id, amount)         // recorded interaction
  }

  def recorded: List[Operation] = journal.toList        // test-only accessor
}
